        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Raw meeting content"],
        "outputs": ["Clarified decisions and action item details"]
      },
      {
        "id": "A3",
        "name": "Draft meeting summary",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Raw meeting content", "Clarified decisions and action item details"],
        "outputs": ["Draft meeting summary including decisions, action items, and owners"]
      },
      {
        "id": "A4",
        "name": "Attach supporting materials (if any)",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Draft meeting summary", "Supporting documents or files"],
        "outputs": ["Meeting summary with attachments"]
      },
      {
        "id": "A5",
        "name": "Determine recipient list",
        "actor": "Minute taker",
        "system": "Unknown",
        "inputs": ["Meeting context", "Attendee information"],
        "outputs": ["List of relevant email recipients"]
      },
      {
        "id": "A6",
        "name": "Send summary email to recipients",
        "actor": "Minute taker",
        "system": "Email client",
        "inputs": ["Meeting summary with attachments", "List of relevant email recipients"],
        "outputs": ["Sent summary email"]
      }
    ],
    "decisions": [
      {
        "id": "D1",
        "condition": "Are there unclear items in the notes or transcript that require clarification?",
        "branches": [
          "Yes — confirm with relevant decision owners before drafting (proceed to A2)",
          "No — proceed directly to drafting (proceed to A3)"
        ]
      },
      {
        "id": "D2",
        "condition": "Are there supporting materials to attach to the summary?",
        "branches": [
          "Yes — attach materials (proceed to A4)",
          "No — skip attachment step (proceed to A5)"
        ]
      }
    ],
    "exceptions": [
      "Decision owner is unavailable to clarify unclear items, causing delay in drafting",
      "Meeting notes or transcript are incomplete or missing, preventing accurate summarization",
      "Recipient list is ambiguous, risking omission of relevant stakeholders or inclusion of unintended recipients"
