    {
      "target": "A1 — Collect meeting notes or transcript",
      "rationale": "Conferencing and transcription tools can automatically capture and deliver transcripts at meeting end, eliminating the manual collection step.",
      "required_data": ["Integration with conferencing platform", "Automatic transcript generation capability"],
      "constraints": ["Meeting must be conducted on a supported platform", "Participant consent for recording may be required"],
      "confidence": "high"
    },
    {
      "target": "A3 — Draft meeting summary",
      "rationale": "AI-based summarization tools can extract decisions, action items, and owners from transcripts or notes, reducing manual drafting effort. Identified as an explicit opportunity by the domain expert.",
      "required_data": ["Structured or unstructured transcript or notes", "Defined output schema (decisions, action items, owners)"],
      "constraints": ["Quality of AI output depends on transcript clarity", "Human review recommended before sending", "Data privacy considerations for meeting content"],
      "confidence": "medium"
    },
    {
      "target": "A5 — Determine recipient list",
      "rationale": "Calendar or meeting platform data can automatically derive attendee lists, which could serve as a default recipient list.",
      "required_data": ["Meeting calendar event with attendee metadata", "Rules for including or excluding non-attendees"],
      "constraints": ["Recipient scope may extend beyond attendees in some cases, requiring manual override", "Determination method is currently unspecified"],
      "confidence": "medium"
    },
    {
      "target": "A6 — Send summary email to recipients",
      "rationale": "Once the summary and recipient list are finalized, email dispatch can be automated via integration with an email platform.",
      "required_data": ["Finalized summary content", "Confirmed recipient list", "Email platform API or integration"],
      "constraints": ["Should only trigger after human confirmation of summary accuracy", "No time limit is specified, so scheduling flexibility exists"],
